<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { api, rootApi, idempotencyKey, errorMessage } from '../services/api'
import { useCartStore } from '../stores/cart'
import { useAuthStore } from '../stores/auth'
import { useFeedbackStore } from '../stores/feedback'
const cart = useCartStore(); const auth = useAuthStore(); const feedback = useFeedbackStore(); const router = useRouter(); const submitting = ref(false); const notes = ref(''); const customers = ref([]); const selectedCustomer = ref(null); const customerQ = ref(''); const minimumTotal = 250; const selectedCustomerStorageKey = 'villas_cart_customer_id'
const money = v => `${Number(v || 0).toFixed(2)} €`
const total = computed(() => Number(cart.cart.total || 0)); const remaining = computed(() => Math.max(0, minimumTotal - total.value)); const meetsMinimum = computed(() => total.value >= minimumTotal); const customerItems = computed(() => customers.value.filter(customer => !customerQ.value || `${customer.fullName} ${customer.companyName} ${customer.username}`.toLowerCase().includes(customerQ.value.toLowerCase())))
onMounted(async () => { try { await cart.load(); if (auth.isAdmin) { customers.value = (await api.get('/admin/users?role=client&active=true')).data.users; const saved = Number(localStorage.getItem(selectedCustomerStorageKey)); if (saved && customers.value.some(customer => customer.id === saved)) selectedCustomer.value = saved } } catch(e) { feedback.show(errorMessage(e), 'error') } })
watch(selectedCustomer, value => { if (auth.isAdmin) { if (value) localStorage.setItem(selectedCustomerStorageKey, String(value)); else localStorage.removeItem(selectedCustomerStorageKey) } })
async function remove(item) { if (!await feedback.confirm(`Remover ${item.name} do carrinho?`)) return; try { await cart.remove(item); feedback.show('Produto removido.') } catch(e) { feedback.show(errorMessage(e), 'error') } }
async function update(item, value) { const qty = Number(value); if (qty < item.quantity_step || qty % item.quantity_step) return feedback.show(`Use múltiplos de ${item.quantity_step}.`, 'warning'); try { await cart.update(item, qty) } catch(e) { await cart.load(); feedback.show(errorMessage(e), 'error') } }
function adjust(item, direction) { update(item, Number(item.quantity) + direction * Number(item.quantity_step)) }
async function submit() { if (auth.isAdmin && !selectedCustomer.value) return feedback.show('Selecione o cliente para esta encomenda.', 'warning'); if (!meetsMinimum.value) return feedback.show(`Faltam ${money(remaining.value)} para o mínimo de 250,00 €.`, 'warning'); if (!await feedback.confirm('Confirmar e enviar esta encomenda?', 'Criar encomenda')) return; submitting.value = true; try { const { data } = await rootApi.post('/me/orders', { idempotency_key: idempotencyKey('order'), cart_revision: cart.cart.revision, notes: notes.value, customer_user_id: auth.isAdmin ? selectedCustomer.value : null }); cart.cart = { items: [], revision: cart.cart.revision + 1, units: 0, lines: 0, total: '0.00', subtotal: '0.00' }; if (auth.isAdmin) localStorage.removeItem(selectedCustomerStorageKey); feedback.show('Encomenda criada com sucesso.'); router.push(auth.isAdmin ? `/admin/encomendas/${data.order.publicNumber}` : `/encomendas/${data.order.publicNumber}`) } catch(e) { if (e?.response?.data?.detail === 'cart_revision_mismatch') await cart.load(); feedback.show(errorMessage(e), 'error') } finally { submitting.value = false } }
</script>
<template><div class="page"><div class="page-head"><div><h1>Carrinho</h1><p>{{ cart.cart.lines }} linhas · {{ cart.cart.units }} unidades</p></div><v-btn to="/catalogo" variant="tonal" prepend-icon="mdi-plus">Adicionar produtos</v-btn></div>
  <v-progress-linear v-if="cart.loading" indeterminate color="secondary" />
  <v-row v-else-if="cart.cart.items.length"><v-col cols="12" lg="8"><v-card class="soft-card"><v-list lines="three"><template v-for="(item, i) in cart.cart.items" :key="item.id"><v-divider v-if="i" /><v-list-item class="py-4"><template #prepend><v-avatar rounded="lg" size="72" color="grey-lighten-3"><v-img v-if="item.image_path" :src="`/media/${item.image_path}`" /><v-icon v-else>mdi-package-variant</v-icon></v-avatar></template><v-list-item-title class="font-weight-bold">{{ item.name }}</v-list-item-title><v-list-item-subtitle>{{ item.ref }} · {{ [item.color, item.size].filter(Boolean).join(' · ') || item.type }}</v-list-item-subtitle><template #append><div class="d-flex align-center ga-3"><div class="quantity-control"><v-btn icon="mdi-minus" size="small" variant="tonal" :disabled="item.quantity <= item.quantity_step" @click="adjust(item,-1)" /><b>{{ item.quantity }}</b><v-btn icon="mdi-plus" size="small" variant="tonal" @click="adjust(item,1)" /></div><div class="font-weight-bold text-right" style="width:92px">{{ money(item.line_total) }}</div><v-btn icon="mdi-delete-outline" variant="text" color="error" @click="remove(item)" /></div></template></v-list-item></template></v-list></v-card></v-col>
    <v-col cols="12" lg="4"><v-card class="soft-card pa-5 position-sticky" style="top:90px"><div class="text-h6 font-weight-bold mb-5">Resumo</div><v-autocomplete v-if="auth.isAdmin" v-model="selectedCustomer" v-model:search="customerQ" :items="customerItems" item-title="fullName" item-value="id" label="Cliente desta encomenda" placeholder="Selecionar cliente" prepend-inner-icon="mdi-account-search-outline" class="mb-2"><template #item="{ props, item }"><v-list-item v-bind="props" :subtitle="item.raw.companyName || item.raw.username" /></template></v-autocomplete><div class="d-flex justify-space-between mb-3"><span class="text-medium-emphasis">Unidades</span><b>{{ cart.cart.units }}</b></div><div class="d-flex justify-space-between mb-5"><span class="text-medium-emphasis">Subtotal</span><b>{{ money(cart.cart.subtotal) }}</b></div><v-divider /><div class="d-flex justify-space-between my-5 text-h6"><span>Total</span><b>{{ money(cart.cart.total) }}</b></div><v-alert v-if="!meetsMinimum" type="warning" variant="tonal" density="compact" class="mb-4">Mínimo de 250,00 € por encomenda. Faltam <b>{{ money(remaining) }}</b>.</v-alert><v-alert v-else type="success" variant="tonal" density="compact" class="mb-4">Mínimo de encomenda atingido.</v-alert><v-textarea v-model="notes" label="Notas da encomenda" rows="3" /><v-btn block color="primary" size="large" :disabled="!meetsMinimum || (auth.isAdmin && !selectedCustomer)" :loading="submitting" @click="submit">Confirmar encomenda</v-btn></v-card></v-col></v-row>
  <div v-else class="empty-state"><v-icon size="64">mdi-cart-outline</v-icon><div class="text-h5 font-weight-bold mt-4">O carrinho está vazio</div><p>Escolha produtos no catálogo para criar uma encomenda.</p><v-btn to="/catalogo" color="primary" class="mt-2">Abrir catálogo</v-btn></div>
</div></template>
<style scoped>
.quantity-control { align-items: center; display: flex; gap: 8px; }
.quantity-control b { min-width: 34px; text-align: center; }
</style>
